package sigepac.mvc.modelos;
import sigepac.mvc.configuracion.ConexionMvc; import java.sql.*; import java.util.*;
public class ModeloPago implements sigepac.mvc.modelos.contratos.IModeloPago {
 public boolean registrarPago(int idNegocio,double monto,String fechaPago,String metodo){if(monto<=0)throw new IllegalArgumentException("El monto a pagar debe ser mayor a cero.");return ConexionMvc.transaccion(()->{
  try(Connection c=ConexionMvc.abrir();PreparedStatement b=c.prepareStatement("SELECT 1 FROM negocios WHERE id_negocio=? AND estado='ACTIVO' FOR UPDATE")){b.setInt(1,idNegocio);try(ResultSet r=b.executeQuery()){if(!r.next())throw new IllegalArgumentException("El negocio no existe o está inactivo.");}}
  List<int[]> ids=new ArrayList<>();List<java.math.BigDecimal> saldos=new ArrayList<>();String q="SELECT id_alquiler,saldo_pendiente FROM alquileres WHERE id_negocio=? AND saldo_pendiente>0 ORDER BY id_alquiler FOR UPDATE";
  try(Connection c=ConexionMvc.abrir();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,idNegocio);try(ResultSet r=p.executeQuery()){while(r.next()){ids.add(new int[]{r.getInt(1)});saldos.add(r.getBigDecimal(2));}}}
  if(ids.isEmpty())throw new IllegalStateException("El negocio no presenta alquileres pendientes.");java.math.BigDecimal restante=java.math.BigDecimal.valueOf(monto).setScale(2,java.math.RoundingMode.HALF_UP);
  for(int i=0;i<ids.size()&&restante.signum()>0;i++){java.math.BigDecimal abono=restante.min(saldos.get(i));java.math.BigDecimal saldo=saldos.get(i).subtract(abono);try(PreparedStatement p=ConexionMvc.abrir().prepareStatement("INSERT INTO pagos(id_alquiler,monto,fecha_pago,metodo_pago) VALUES(?,?,?,?)")){p.setInt(1,ids.get(i)[0]);p.setBigDecimal(2,abono);p.setTimestamp(3,Timestamp.valueOf(fechaPago.length()==10?fechaPago+" 00:00:00":fechaPago));p.setString(4,metodo==null?"EFECTIVO":metodo);p.executeUpdate();}try(PreparedStatement p=ConexionMvc.abrir().prepareStatement("UPDATE alquileres SET saldo_pendiente=?,estado=? WHERE id_alquiler=?")){p.setBigDecimal(1,saldo);p.setString(2,saldo.signum()==0?"PAGADO":"PENDIENTE");p.setInt(3,ids.get(i)[0]);if(p.executeUpdate()!=1)throw new SQLException("No fue posible actualizar el alquiler");}restante=restante.subtract(abono);}
  if(restante.signum()>0)throw new IllegalArgumentException("El monto supera el total de las deudas pendientes.");
  return true;
 });}
 public List<Map<String,Object>> obtenerTodos(){List<Map<String,Object>> out=new ArrayList<>();String q="SELECT p.*,n.nombre nombre_negocio,n.local_numero FROM pagos p JOIN alquileres a ON a.id_alquiler=p.id_alquiler JOIN negocios n ON n.id_negocio=a.id_negocio ORDER BY p.id_pago DESC";try(Connection c=ConexionMvc.abrir();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next()){Map<String,Object> m=new HashMap<>();m.put("id_pago",r.getInt("id_pago"));m.put("id_alquiler",r.getInt("id_alquiler"));m.put("monto",r.getDouble("monto"));m.put("fecha_pago",r.getString("fecha_pago"));m.put("metodo_pago",r.getString("metodo_pago"));m.put("nombre_negocio",r.getString("nombre_negocio"));m.put("local_numero",r.getString("local_numero"));out.add(m);}return out;}catch(SQLException e){throw ConexionMvc.fallo(e);}}
}
